     9	export class BalanceService implements IBalanceService {
    10	  constructor(private readonly repository: IBalanceRepository) {}
    11	
    12	  async getBalance(
    13	    employeeId: string,
    14	    leaveType: string,
    15	  ): Promise<Balance | null> {
    16	    return this.repository.findByEmployeeIdAndLeaveType(employeeId, leaveType);
    17	  }
