    19	  async getBalances(employeeId: string): Promise<Balance[]> {
    20	    return this.repository.findByEmployeeId(employeeId);
    21	  }
    22	
    23	  async hasSufficientBalance(
    24	    employeeId: string,
    25	    leaveType: string,
    26	    requestedDays: number,
    27	  ): Promise<boolean> {
    28	    const balance = await this.repository.findByEmployeeIdAndLeaveType(
    29	      employeeId,
    30	      leaveType,
    31	    );
    32	    if (balance === null) {
    33	      return false;
    34	    }
    35	    return balance.remainingDays >= requestedDays;
    36	  }
    37	
    38	  async deductBalance(
    39	    employeeId: string,
    40	    leaveType: string,
    41	    days: number,
    42	  ): Promise<Balance> {
    43	    const balance = await this.repository.findByEmployeeIdAndLeaveType(
    44	      employeeId,
    45	      leaveType,
    46	    );
    47	
    48	    if (balance === null) {
    49	      throw new BalanceNotFoundError(
    50	        `Balance not found for employee ${employeeId} and leave type ${leaveType}`,
    51	      );
    52	    }
    53	
    54	    if (balance.remainingDays < days) {
    55	      throw new InsufficientBalanceError(
    56	        `Insufficient balance: requested ${days} days but only ${balance.remainingDays} remaining`,
    57	      );
    58	    }
    59	
    60	    const updated = await this.repository.deductDays(balance.id, days);
    61	    if (updated === null) {
    62	      throw new BalanceNotFoundError(
    63	        `Balance not found for id ${balance.id}`,
    64	      );
    65	    }
    66	    return updated;
    67	  }
